export const getOpenLocalUrl = (action: 'finder.open' | 'finder.reveal' | 'file.open' | 'mail.openApp' | 'agent.openInDesktop',) => {




  return `/api/local/${encodeURIComponent(String(action))}`
}

/**
 * @summary Open one registry action on this Mac
 */
export const openLocal = async (action: 'finder.open' | 'finder.reveal' | 'file.open' | 'mail.openApp' | 'agent.openInDesktop',
    localArgs: LocalArgs, options?: Parameters<typeof hubMutator>[1]): Promise<openLocalResponse> => {

  return hubMutator<openLocalResponse>(getOpenLocalUrl(action),
  {
    ...options,
    method: 'POST',
    headers: getHeaders({ 'Content-Type': 'application/json' }, options?.headers),
    body: JSON.stringify(localArgs)
  }
);}


